('<lesson_id>', 'match', replace($blk${"title": "Послушай аудиозапись ещё раз и соедини имена ребят с событиями!", "pairs": [{"left": "Tina", "right": "see a dance show", "right_audio_tts": "see a dance show"}, {"left": "Harry", "right": "go to the cinema", "right_audio_tts": "go to the cinema"}, {"left": "Robert", "right": "birthday party at home", "right_audio_tts": "birthday party at home"}, {"left": "Kelly", "right": "go bowling", "right_audio_tts": "go bowling"}, {"left": "David", "right": "eat at a restaurant", "right_audio_tts": "eat at a restaurant"}]}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 2),
