('<lesson_id>', 'quiz', replace($blk${"title": "Прочитай приглашение ещё раз и ответь на вопросы", "questions": [{"q": "What day is the party going to happen?", "type": "single", "options": [{"text": "Wednesday"}, {"text": "Tuesday"}, {"text": "Friday"}], "correct": [1]}, {"q": "Where is the party going to happen?", "type": "single", "options": [{"text": "At Fun Times Sport Centre"}, {"text": "At Swimming pool"}, {"text": "At School"}], "correct": [0]}, {"q": "What are they going to do first?", "type": "single", "options": [{"text": "play football"}, {"text": "play basketball"}, {"text": "go swimming"}], "correct": [2]}, {"q": "What do they need to bring?", "type": "single", "options": [{"text": "boots"}, {"text": "towels"}, {"text": "hats"}], "correct": [1]}, {"q": "What are they going to eat?", "type": "single", "options": [{"text": "salads"}, {"text": "fruits"}, {"text": "pancakes"}], "correct": [2]}, {"q": "What time is the party going to finish?", "type": "single", "options": [{"text": "at 9 o'clock"}, {"text": "at 6 o'clock"}, {"text": "at 10 o'clock"}], "correct": [0]}]}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 6),
